userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="slideAnimation">▶ Animate lateral translation</button>
<label>
  Lateral displacement
  <input id="lateralDisplacement" type="range" min="-4" max="4" step="0.1" value="0">
  <span id="dispReadout">0.0</span>
</label>
<button id="viewMode">View: 3-D path</button>
<div style="font-size:11px;line-height:1.35;color:#333;margin-top:4px">
  <b>Demo steps</b>
  <button id="step0">1</button>
  <button id="step1">2</button>
  <button id="step2">3</button>
</div>
<div id="narration" style="font-size:11px;line-height:1.35;color:#333;margin-top:4px"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// strip guide → very faint wide BoxGeometry behind the repeated cameras
// sampled camera centers → five identical frustum groups at X = -4,-2,0,2,4
// projection center → SphereGeometry(0.11) black
// image plane rectangle → four black cylinder line segments at z = 0.75
// frustum rays → black cylinder line segments from center to all four rectangle corners
// red translation arrows → red cylinder shafts plus cone arrowheads along lateral path
// active camera → same frustum geometry, black with subtle red highlight ring, translated by slider
// ghost cameras → same frusta at sampled positions with opacity 0.25
// lateral path → straight red translucent cylinder line parallel to image plane
// near/far scene points → orange and blue spheres at depths z=2 and z=5
// projected image points → small orange/blue discs on active image plane
// optical-flow inset → rectangular image plane with before/after points and vector arrows

const uiNarration = document.getElementById('narration');
const dispSlider = document.getElementById('lateralDisplacement');
const dispReadout = document.getElementById('dispReadout');
const animBtn = document.getElementById('slideAnimation');
const modeBtn = document.getElementById('viewMode');

const root = new THREE.Group();
scene.add(root);

const stripGroup = new THREE.Group();
const ghostGroup = new THREE.Group();
const activeGroup = new THREE.Group();
const flowGroup = new THREE.Group();
const pointGroup = new THREE.Group();
root.add(stripGroup, ghostGroup, activeGroup, pointGroup, flowGroup);

const BLACK = 0x000000;
const RED = 0xff0000;
const ORANGE = 0xff9900;
const BLUE = 0x3366cc;

function mat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 1
  });
}

const blackMat = mat(BLACK);
const redMat = mat(RED);
const ghostMat = mat(0x000000, 0.25);
const orangeMat = mat(ORANGE);
const blueMat = mat(BLUE);

function cylinderBetween(a, b, radius, material, name = '') {
  const start = a.clone();
  const end = b.clone();
  const mid = start.clone().add(end).multiplyScalar(0.5);
  const dir = end.clone().sub(start);
  const len = dir.length();
  const geom = new THREE.CylinderGeometry(radius, radius, len, 10);
  const mesh = new THREE.Mesh(geom, material);
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  mesh.name = name;
  return mesh;
}

function coneArrowHead(pos, dir, radius, length, material) {
  const geom = new THREE.ConeGeometry(radius, length, 24);
  const cone = new THREE.Mesh(geom, material);
  cone.position.copy(pos);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return cone;
}

function makeFrustum(material, opacityOffsetZ = 0, lineRadius = 0.025) {
  const g = new THREE.Group();
  const c = new THREE.Vector3(0, -0.55, 0 + opacityOffsetZ);
  const z = 0.75 + opacityOffsetZ;
  const hw = 0.475;
  const hh = 0.275;
  const corners = [
    new THREE.Vector3(-hw, 0.45 - hh, z),
    new THREE.Vector3(hw, 0.45 - hh, z),
    new THREE.Vector3(hw, 0.45 + hh, z),
    new THREE.Vector3(-hw, 0.45 + hh, z)
  ];

  const sphere = new THREE.Mesh(new THREE.SphereGeometry(0.11, 32, 16), material);
  sphere.position.copy(c);
  g.add(sphere);

  for (let i = 0; i < 4; i++) {
    g.add(cylinderBetween(corners[i], corners[(i + 1) % 4], lineRadius, material, 'image plane edge'));
  }
  for (const p of corners) {
    g.add(cylinderBetween(c, p, lineRadius, material, 'frustum ray'));
  }
  return g;
}

const sampleXs = [-4, -2, 0, 2, 4];

const bg = new THREE.Mesh(
  new THREE.BoxGeometry(12.4, 0.03, 0.03),
  mat(0xffffff)
);
bg.position.set(0, -1.05, 0);
stripGroup.add(bg);

for (const x of sampleXs) {
  const f = makeFrustum(blackMat, 0, 0.022);
  f.position.x = x;
  stripGroup.add(f);
}

function makeArrow(x0, x1, y = -0.72, z = -0.08) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3(1, 0, 0);
  const headLen = 0.26;
  const start = new THREE.Vector3(x0, y, z);
  const shaftEnd = new THREE.Vector3(x1 - headLen, y, z);
  g.add(cylinderBetween(start, shaftEnd, 0.045, redMat, 'red arrow shaft'));
  const head = coneArrowHead(new THREE.Vector3(x1 - headLen / 2, y, z), dir, 0.14, headLen, redMat);
  head.rotation.z += -Math.PI / 2;
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  g.add(head);
  return g;
}

const arrowRanges = [
  [-5.95, -4.75],
  [-3.35, -2.15],
  [-1.35, -0.15],
  [0.65, 1.85],
  [2.65, 3.85],
  [4.75, 5.95]
];
for (const r of arrowRanges) stripGroup.add(makeArrow(r[0], r[1]));

for (const x of sampleXs) {
  const f = makeFrustum(ghostMat, -0.015, 0.02);
  f.position.x = x;
  ghostGroup.add(f);
}

const activeFrustum = makeFrustum(blackMat, 0.025, 0.028);
activeGroup.add(activeFrustum);
const activeHalo = new THREE.Mesh(
  new THREE.TorusGeometry(0.16, 0.018, 8, 32),
  mat(0xff3333, 0.75)
);
activeHalo.position.set(0, -0.55, 0.04);
activeHalo.rotation.x = Math.PI / 2;
activeFrustum.add(activeHalo);

const pathLine = cylinderBetween(
  new THREE.Vector3(-4, -0.55, -0.18),
  new THREE.Vector3(4, -0.55, -0.18),
  0.018,
  mat(0xff0000, 0.35),
  'lateral path'
);
activeGroup.add(pathLine);

const pNear = new THREE.Vector3(0.6, 0.1, 2.0);
const pFar = new THREE.Vector3(0.6, 0.1, 5.0);
const nearSphere = new THREE.Mesh(new THREE.SphereGeometry(0.09, 24, 12), orangeMat);
nearSphere.position.copy(pNear);
const farSphere = new THREE.Mesh(new THREE.SphereGeometry(0.09, 24, 12), blueMat);
farSphere.position.copy(pFar);
pointGroup.add(nearSphere, farSphere);

const nearRayMat = mat(ORANGE, 0.45);
const farRayMat = mat(BLUE, 0.45);
let nearRay = null;
let farRay = null;
let nearProj = new THREE.Mesh(new THREE.SphereGeometry(0.055, 18, 10), orangeMat);
let farProj = new THREE.Mesh(new THREE.SphereGeometry(0.055, 18, 10), blueMat);
pointGroup.add(nearProj, farProj);

function makeFlowInset() {
  const g = new THREE.Group();
  g.position.set(0, 0.12, -0.95);

  const edgeMat = mat(0x222222, 0.75);
  const w = 2.65, h = 1.15;
  const z = 0;
  const a = new THREE.Vector3(-w / 2, -h / 2, z);
  const b = new THREE.Vector3(w / 2, -h / 2, z);
  const c = new THREE.Vector3(w / 2, h / 2, z);
  const d = new THREE.Vector3(-w / 2, h / 2, z);
  g.add(cylinderBetween(a, b, 0.012, edgeMat));
  g.add(cylinderBetween(b, c, 0.012, edgeMat));
  g.add(cylinderBetween(c, d, 0.012, edgeMat));
  g.add(cylinderBetween(d, a, 0.012, edgeMat));

  return g;
}
const inset = makeFlowInset();
flowGroup.add(inset);

let flowObjects = [];
function clearFlowObjects() {
  for (const o of flowObjects) {
    o.parent?.remove(o);
    o.traverse?.(m => {
      m.geometry?.dispose?.();
      if (Array.isArray(m.material)) m.material.forEach(mm => mm.dispose?.());
      else m.material?.dispose?.();
    });
  }
  flowObjects = [];
}

function addPointDisc(parent, x, y, material, r = 0.055) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 20, 10), material);
  m.position.set(x, y, 0.03);
  parent.add(m);
  flowObjects.push(m);
  return m;
}

function addFlowArrow(parent, x0, y0, x1, y1, material) {
  const a = new THREE.Vector3(x0, y0, 0.04);
  const b = new THREE.Vector3(x1, y1, 0.04);
  const dir = b.clone().sub(a).normalize();
  const len = a.distanceTo(b);
  if (len < 0.03) return;
  const shaftEnd = a.clone().add(dir.clone().multiplyScalar(Math.max(0.02, len - 0.12)));
  const shaft = cylinderBetween(a, shaftEnd, 0.015, material);
  const head = coneArrowHead(b.clone().sub(dir.clone().multiplyScalar(0.055)), dir, 0.055, 0.12, material);
  parent.add(shaft, head);
  flowObjects.push(shaft, head);
}

const fProject = 1.0;
const imageScale = 0.34;
let lateralDisplacement = 0;
let viewMode = '3-D path';
let animating = false;
let animStart = performance.now();

function imagePlanePointFor(P, T) {
  const u = fProject * (P.x - T) / P.z;
  return new THREE.Vector3(T + u * 0.55, 0.45 + P.y * 0.35, 0.75);
}

function updateProjectionGeometry() {
  activeFrustum.position.x = lateralDisplacement;
  activeGroup.position.x = 0;

  if (nearRay) {
    pointGroup.remove(nearRay);
    pointGroup.remove(farRay);
  }

  const center = new THREE.Vector3(lateralDisplacement, -0.55, 0.025);
  const np = imagePlanePointFor(pNear, lateralDisplacement);
  const fp = imagePlanePointFor(pFar, lateralDisplacement);
  nearProj.position.copy(np);
  farProj.position.copy(fp);

  nearRay = cylinderBetween(center, pNear, 0.01, nearRayMat);
  farRay = cylinderBetween(center, pFar, 0.01, farRayMat);
  pointGroup.add(nearRay, farRay);

  clearFlowObjects();
  const uN0 = fProject * pNear.x / pNear.z;
  const uF0 = fProject * pFar.x / pFar.z;
  const uN1 = fProject * (pNear.x - lateralDisplacement) / pNear.z;
  const uF1 = fProject * (pFar.x - lateralDisplacement) / pFar.z;
  const yN = 0.24;
  const yF = -0.24;
  const xN0 = uN0 * imageScale;
  const xF0 = uF0 * imageScale;
  const xN1 = uN1 * imageScale;
  const xF1 = uF1 * imageScale;

  addPointDisc(inset, xN0, yN, mat(ORANGE, 0.45), 0.045);
  addPointDisc(inset, xF0, yF, mat(BLUE, 0.45), 0.045);
  addPointDisc(inset, xN1, yN, orangeMat, 0.06);
  addPointDisc(inset, xF1, yF, blueMat, 0.06);
  addFlowArrow(inset, xN0, yN, xN1, yN, mat(0xff6600));
  addFlowArrow(inset, xF0, yF, xF1, yF, mat(BLUE));

  dispReadout.textContent = lateralDisplacement.toFixed(1);
  dispSlider.value = lateralDisplacement.toFixed(1);
}

function setMode(next) {
  viewMode = next;
  modeBtn.textContent = 'View: ' + viewMode;
  const projected = viewMode === 'Projected optical flow';
  flowGroup.visible = projected;
  pointGroup.visible = true;
  activeGroup.visible = !projected;
  ghostGroup.visible = !projected;
  stripGroup.traverse(o => {
    if (o.material && o.material.transparent !== undefined && projected) {
      if (o.material.color && o.material.color.getHex() === BLACK) {
        o.material.opacity = 0.16;
        o.material.transparent = true;
      }
    }
  });
  if (!projected) {
    stripGroup.traverse(o => {
      if (o.material && o.material.color && o.material.color.getHex() === BLACK) {
        o.material.opacity = 1;
        o.material.transparent = false;
      }
    });
  }
  updateProjectionGeometry();
}

function setDisplacement(v) {
  lateralDisplacement = Math.max(-4, Math.min(4, Number(v)));
  updateProjectionGeometry();
}

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.62
});

addLabel('sideways camera translation', new THREE.Vector3(0, -0.98, -0.2), {
  color: '#cc0000',
  fontSize: '14px',
  bold: true,
  offset: [0, 8]
});
addLabel('near point', pNear.clone().add(new THREE.Vector3(0.15, 0.16, 0)), {
  color: '#cc6600',
  fontSize: '12px',
  background: 'rgba(255,255,255,0.72)'
});
addLabel('far point', pFar.clone().add(new THREE.Vector3(0.15, 0.16, 0)), {
  color: '#224a99',
  fontSize: '12px',
  background: 'rgba(255,255,255,0.72)'
});
addLabel('image-plane optical flow: near vector is longer', new THREE.Vector3(0, 1.05, -0.95), {
  color: '#111',
  fontSize: '13px',
  bold: true,
  background: 'rgba(255,255,255,0.78)'
});

registerInteractive(activeFrustum, {
  title: 'Active laterally translating camera',
  tooltip: 'The active frustum slides sideways while its optical axis stays fixed.',
  body: 'This camera changes only its lateral X position. Its image plane stays parallel to the ghost positions, so the motion has no forward component along the optical axis.'
});
registerInteractive(nearSphere, {
  title: 'Near 3-D point',
  tooltip: 'Near point: larger projected shift',
  body: 'For lateral translation, image shift is proportional to 1/Z. At Z = 2, this point shifts about 2.5 times more than the far point at Z = 5.'
});
registerInteractive(farSphere, {
  title: 'Far 3-D point',
  tooltip: 'Far point: smaller projected shift',
  body: 'The farther point has a smaller optical-flow vector because the same camera translation is divided by a larger depth.'
});

dispSlider.addEventListener('input', () => {
  animating = false;
  animBtn.textContent = '▶ Animate lateral translation';
  setDisplacement(dispSlider.value);
});

animBtn.addEventListener('click', () => {
  animating = !animating;
  animStart = performance.now() - ((lateralDisplacement + 4) / 8) * 6000;
  animBtn.textContent = animating ? '⏸ Pause lateral translation' : '▶ Animate lateral translation';
});

modeBtn.addEventListener('click', () => {
  setMode(viewMode === '3-D path' ? 'Projected optical flow' : '3-D path');
});

const demoSteps = [
  {
    title: 'Sideways camera path',
    narration: 'The camera copies form a left-to-right strip, and every red arrow points horizontally. The frustum orientation does not change, so the camera is translating parallel to the image plane rather than moving forward.',
    state: { lateralDisplacement: 0, viewMode: '3-D path' }
  },
  {
    title: 'Displace the active camera',
    narration: 'Move the active frustum to the right. The camera center shifts laterally while the rectangular image plane remains parallel to its starting pose.',
    state: { lateralDisplacement: 3, viewMode: '3-D path' }
  },
  {
    title: 'Optical flow from lateral motion',
    narration: 'Switch to the projection view. The near point’s image vector is visibly longer than the far point’s vector, showing the inverse-depth dependence of lateral-motion parallax.',
    state: { lateralDisplacement: 3, viewMode: 'Projected optical flow' }
  }
];

function goToStep(i) {
  const s = demoSteps[i];
  if (!s) return;
  animating = false;
  animBtn.textContent = '▶ Animate lateral translation';
  setDisplacement(s.state.lateralDisplacement);
  setMode(s.state.viewMode);
  uiNarration.innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
}
window.goToStep = goToStep;

document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));

function tickLateralAnimation() {
  requestAnimationFrame(tickLateralAnimation);
  if (!animating) return;
  const t = ((performance.now() - animStart) % 6000) / 6000;
  const v = -4 + 8 * t;
  setDisplacement(v);
}
tickLateralAnimation();

setMode('3-D path');
goToStep(0);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
