userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="slideAnimation">▶ Animate lateral translation</button>
<label>
  Lateral displacement
  <input id="lateralDisplacement" type="range" min="0" max="1" step="0.01" value="0">
  <span id="dispReadout">0.00</span>
</label>
<div style="font-size:11px;line-height:1.35;color:#333;margin-top:4px">
  <b>Demo steps</b>
  <button id="step0">1</button>
  <button id="step1">2</button>
  <button id="step2">3</button>
</div>
<div id="narration" style="font-size:11px;line-height:1.35;color:#333;margin-top:4px"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// camera strip root → Group containing only flat front-on source elements
// camera icons → five identical black outline groups in the XY plane
// camera image rectangle → four thick black CylinderGeometry segments
// camera construction diagonals → four thick black CylinderGeometry segments from rectangle corners to lens
// camera lens/pinhole → black CircleGeometry disk below each rectangle
// red translation arrows → six uniform filled red ShapeGeometry arrows, all horizontal in the XY plane

const uiNarration = document.getElementById('narration');
const dispSlider = document.getElementById('lateralDisplacement');
const dispReadout = document.getElementById('dispReadout');
const animBtn = document.getElementById('slideAnimation');

const BLACK = 0x000000;
const RED = 0xff0000;

const blackMat = new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.DoubleSide });
const redMat = new THREE.MeshBasicMaterial({ color: RED, side: THREE.DoubleSide });

const stripRoot = new THREE.Group();
const cameraRow = new THREE.Group();
const arrowRow = new THREE.Group();
stripRoot.add(arrowRow, cameraRow);
scene.add(stripRoot);

function cylinderBetween(a, b, radius, material) {
  const dir = b.clone().sub(a);
  const len = dir.length();
  const geom = new THREE.CylinderGeometry(radius, radius, len, 16);
  const mesh = new THREE.Mesh(geom, material);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

function makeFlatCameraIcon() {
  const g = new THREE.Group();

  const halfW = 0.42;
  const bottomY = 0.02;
  const topY = 0.52;
  const lensY = -0.30;
  const lensR = 0.085;
  const zLine = 0.035;
  const zLens = 0.055;
  const lineR = 0.026;

  const tl = new THREE.Vector3(-halfW, topY, zLine);
  const tr = new THREE.Vector3( halfW, topY, zLine);
  const br = new THREE.Vector3( halfW, bottomY, zLine);
  const bl = new THREE.Vector3(-halfW, bottomY, zLine);
  const lens = new THREE.Vector3(0, lensY, zLine);

  g.add(cylinderBetween(tl, tr, lineR, blackMat));
  g.add(cylinderBetween(tr, br, lineR, blackMat));
  g.add(cylinderBetween(br, bl, lineR, blackMat));
  g.add(cylinderBetween(bl, tl, lineR, blackMat));

  g.add(cylinderBetween(tl, lens, lineR, blackMat));
  g.add(cylinderBetween(tr, lens, lineR, blackMat));
  g.add(cylinderBetween(bl, lens, lineR, blackMat));
  g.add(cylinderBetween(br, lens, lineR, blackMat));

  const disk = new THREE.Mesh(new THREE.CircleGeometry(lensR, 40), blackMat);
  disk.position.set(0, lensY, zLens);
  g.add(disk);

  return g;
}

function makeHorizontalArrow(x0, x1, y) {
  const headLen = 0.25;
  const shaftHalf = 0.040;
  const headHalf = 0.145;
  const z = 0.012;

  const s = new THREE.Shape();
  s.moveTo(x0, y - shaftHalf);
  s.lineTo(x1 - headLen, y - shaftHalf);
  s.lineTo(x1 - headLen, y - headHalf);
  s.lineTo(x1, y);
  s.lineTo(x1 - headLen, y + headHalf);
  s.lineTo(x1 - headLen, y + shaftHalf);
  s.lineTo(x0, y + shaftHalf);
  s.lineTo(x0, y - shaftHalf);

  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(s), redMat);
  mesh.position.z = z;
  return mesh;
}

const cameraXs = [-3.7, -1.85, 0, 1.85, 3.7];
for (const x of cameraXs) {
  const cam = makeFlatCameraIcon();
  cam.position.x = x;
  cameraRow.add(cam);
  registerInteractive(cam, {
    title: 'Camera position',
    tooltip: 'One repeated camera snapshot in a lateral translation sequence.',
    body: 'The icon is drawn front-on: the rectangular image plane stays parallel while the camera positions repeat along a straight horizontal path.'
  });
}

const arrowY = -0.36;
const arrowLen = 0.93;
const arrowCenters = [-4.55, -2.775, -0.925, 0.925, 2.775, 4.55];
for (const cx of arrowCenters) {
  const arrow = makeHorizontalArrow(cx - arrowLen / 2, cx + arrowLen / 2, arrowY);
  arrowRow.add(arrow);
  registerInteractive(arrow, {
    title: 'Lateral translation direction',
    tooltip: 'All red arrows point horizontally to the right.',
    body: 'The uniform red arrows indicate repeated sideways camera translation. There is no forward depth motion in this source figure.'
  });
}

let displacement = 0;
let animating = false;
let animStart = performance.now();

function setDisplacement(v) {
  displacement = Math.max(0, Math.min(1, Number(v) || 0));
  cameraRow.position.x = displacement * 0.34;
  dispSlider.value = displacement.toFixed(2);
  dispReadout.textContent = displacement.toFixed(2);
}

const demoSteps = [
  {
    title: 'Source figure view',
    text: 'Five bold black camera icons form a straight horizontal strip. Six red arrows are horizontal, uniform, and aligned with the camera centers.'
  },
  {
    title: 'Scrub lateral displacement',
    text: 'Move the slider to nudge the camera snapshots in the arrow direction while preserving the same front-on geometry.'
  },
  {
    title: 'Animate the translation',
    text: 'Animation repeatedly slides the camera snapshots to the right, matching the simple lateral-motion cue in the reference.'
  }
];

function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  if (i === 0) {
    animating = false;
    animBtn.textContent = '▶ Animate lateral translation';
    setDisplacement(0);
  } else if (i === 1) {
    animating = false;
    animBtn.textContent = '▶ Animate lateral translation';
    setDisplacement(0.55);
  } else if (i === 2) {
    animating = true;
    animStart = performance.now();
    animBtn.textContent = '⏸ Pause lateral translation';
  }
  uiNarration.innerHTML = '<b>' + step.title + '</b><br>' + step.text;
}

dispSlider.addEventListener('input', () => {
  animating = false;
  animBtn.textContent = '▶ Animate lateral translation';
  setDisplacement(dispSlider.value);
});

animBtn.addEventListener('click', () => {
  animating = !animating;
  if (animating) {
    animStart = performance.now() - displacement * 1800;
    animBtn.textContent = '⏸ Pause lateral translation';
    uiNarration.innerHTML = '<b>Animate the translation</b><br>The camera snapshots slide horizontally in the same direction as the red arrows.';
  } else {
    animBtn.textContent = '▶ Animate lateral translation';
  }
});

document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));

function tickSourceStrip() {
  requestAnimationFrame(tickSourceStrip);
  if (!animating) return;
  const t = ((performance.now() - animStart) % 1800) / 1800;
  setDisplacement(t);
}
tickSourceStrip();

controls.enableRotate = false;
controls.enablePan = true;
controls.enableZoom = true;

setCameraView({
  projection: 'orthographic',
  azimuthDeg: 90,
  elevationDeg: 0,
  target: [0, 0.08, 0],
  heightFraction: 0.92,
  distanceScale: 1.0
});

setDisplacement(0);
goToStep(0);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
{"next_step":"refine_generation","rationale":"The concept is present but execution has multiple implementation-level issues — color mismatches, missing interactions, wrong camera angle, scale errors — all fixable by the generator without changing the plan."}

Example 3 → fix_plan
{"failure_modes":["Missing-Labels","Interaction-Missing","Camera-Wrong","Color-Wrong","Concept-Misunderstood"],"geometry_accuracy":2,"interactivity_usability":2,"faithfulness":2,"label_quality":2,"concept_accuracy":2,"overall_average":2,"notes":"Discrepancies in elements and labels, with limited interactivity and conceptual errors."}
{"next_step":"fix_plan","rationale":"Concept-Misunderstood failure mode and all scores at 2/5 indicate the plan failed to correctly decompose the figure — the generator cannot fix a fundamentally wrong conceptual structure."}
